/* One A4 landscape page (the sizes below are CSS px at 96 per inch: 1122 x 793).
   Every rule is scoped under .certificate-container: Frappe's own print stylesheet sets margins
   on `.print-format p` and `.print-format h1`, which a bare class would lose to. */
.print-format {
    /* The page is given as exact dimensions (A4 landscape), not as orientation plus a size: Frappe's
       Chrome path injects its own @page size from the portrait paper size, which wins over both
       `orientation: Landscape` and an @page rule here. */
    page-width: 297mm;
    page-height: 210mm;
    margin-top: 0;
    margin-bottom: 0;
    margin-left: 0;
    margin-right: 0;
}

@page {
    size: A4 landscape;
    margin: 0;
}

.certificate-container {
    position: relative;
    display: flex;
    width: 1122px;
    height: 793px;
    box-sizing: border-box;
    overflow: hidden;
    background: #ffffff;
    color: #3c210e;
    font-family: "Archivo", system-ui, sans-serif;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.certificate-container .certificate-band {
    position: relative;
    flex: 0 0 340px;
    box-sizing: border-box;
    padding: 60px 36px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    background: #f8c4b7;
    overflow: hidden;
}

.certificate-container .certificate-ring {
    position: absolute;
    border-radius: 999px;
    border: 1.5px solid rgba(255, 255, 255, 0.7);
}

.certificate-container .certificate-ring-1 {
    width: 420px;
    height: 420px;
    left: -150px;
    top: 250px;
}

.certificate-container .certificate-ring-2 {
    width: 300px;
    height: 300px;
    left: -80px;
    top: 310px;
}

.certificate-container .certificate-logo {
    position: relative;
    display: block;
    width: 100%;
    height: auto;
}

.certificate-container .certificate-seal {
    position: relative;
    display: block;
    width: 112px;
    height: 112px;
}

.certificate-container .certificate-body {
    flex: 1 1 auto;
    min-width: 0;
    box-sizing: border-box;
    padding: 76px 80px 60px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
}

.certificate-container .certificate-title {
    margin: 0;
    font-size: 46px;
    font-weight: 500;
    letter-spacing: -0.01em;
    line-height: 1.08;
}

.certificate-container .certificate-rule {
    display: block;
    width: 56px;
    height: 4px;
    margin-top: 20px;
    border-radius: 999px;
    background: #f8c4b7;
}

.certificate-container .certificate-lead {
    margin: 30px 0 0;
    font-size: 19px;
    line-height: 1.3;
    color: #665f59;
}

.certificate-container .certificate-lead-course {
    margin-top: 20px;
}

.certificate-container .certificate-recipient {
    margin: 8px 0 0;
    padding: 0 14px 0 0;
    font-size: 54px;
    font-weight: 500;
    line-height: 1.12;
    background: linear-gradient(transparent 64%, #f8c4b7 64%);
}

.certificate-container .certificate-course {
    margin: 6px 0 0;
    font-size: 31px;
    font-weight: 500;
    line-height: 1.2;
}

.certificate-container .certificate-assessments {
    margin: 8px 0 0;
    font-size: 16px;
    line-height: 1.3;
    color: #665f59;
}

.certificate-container .certificate-details {
    display: flex;
    flex-wrap: wrap;
    margin: 34px 0 0;
    padding: 0;
}

.certificate-container .certificate-detail {
    display: flex;
    flex-direction: column-reverse;
    align-items: flex-start;
    gap: 6px;
    padding: 2px 30px;
    border-left: 1px solid rgba(60, 33, 14, 0.25);
}

.certificate-container .certificate-detail:first-child {
    padding-left: 0;
    border-left: 0;
}

.certificate-container .certificate-detail dt {
    margin: 0;
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #665f59;
}

.certificate-container .certificate-detail dd {
    margin: 0;
    font-size: 30px;
    font-weight: 400;
    line-height: 1.1;
}

.certificate-container .certificate-signatories {
    margin-top: auto;
    display: flex;
    align-items: flex-end;
    gap: 72px;
}

.certificate-container .certificate-signatory {
    display: flex;
    flex-direction: column;
    width: 280px;
}

/* Room above the line for a signature image later. */
.certificate-container .certificate-signature-space {
    display: block;
    height: 58px;
    width: 100%;
}

.certificate-container .certificate-signature-line {
    border-bottom: 1.5px solid #3c210e;
}

.certificate-container .certificate-role {
    margin: 4px 0 0;
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #665f59;
}

.certificate-container .certificate-people {
    margin: 10px 0 0;
    font-size: 19px;
    line-height: 1.35;
}

.certificate-container .certificate-people strong {
    font-weight: 500;
}
